VALUES
(
    gen_random_uuid(),
    'en_IN',
    'WS_BILL_GEN_COMPLETION_EMAIL_TEMPLATE',
    '<h2>Water Bill Generation Report - {primaryCity} ({completedOn})</h2> <!DOCTYPE html> <html> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> </head> <body style="margin:0; padding:24px 10px; background-color:#eef2f6; font-family:-apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; -webkit-font-smoothing:antialiased;"> <!-- Outer Centering Table --> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="background-color:#eef2f6; width:100%;"> <tr> <td align="center" style="padding:10px 0 30px;"> <!-- Main Card Container --> <table width="680" border="0" cellpadding="0" cellspacing="0" style="width:680px; max-width:680px; background-color:#ffffff; border-radius:18px; overflow:hidden; box-shadow:0 12px 35px rgba(15,23,42,0.12); border:1px solid #e2e8f0;"> <!-- HERO HEADER --> <tr> <td style="background:linear-gradient(135deg, #0b1220 0%, #161e38 50%, #0c2b48 100%); padding:32px 36px 30px; color:#ffffff;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <td> <table border="0" cellpadding="0" cellspacing="0"> <tr> <td width="42" valign="middle"> <div style="width:40px; height:40px; background:linear-gradient(135deg, #6366f1 0%, #06b6d4 100%); border-radius:12px; text-align:center; line-height:40px; font-weight:800; font-size:20px; color:#ffffff;">m</div> </td> <td style="padding-left:14px;" valign="middle"> <div style="font-size:11px; font-weight:800; letter-spacing:1.5px; text-transform:uppercase; color:#94a3b8;">mSeva UPYOG</div> <div style="font-size:12px; color:#cbd5e1; margin-top:2px;">Water &amp; Sewerage Calculation Engine</div> </td> </tr> </table> </td> <td align="right" valign="top"> <span style="display:inline-block; padding:6px 14px; background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.15); border-radius:30px; font-size:11px; font-weight:600; color:#e2e8f0;">{completedOn}</span> </td> </tr> <tr> <td colspan="2" style="padding-top:26px;"> <div style="font-size:26px; font-weight:800; letter-spacing:-0.5px; color:#ffffff; line-height:1.2;">Water Bill Generation Report</div> <div style="font-size:13px; color:#94a3b8; margin-top:6px;">Batch execution completed for <strong style="color:#38bdf8;">{primaryCity}</strong> ({primaryTenant})</div> </td> </tr> <!-- Meta Chips --> <tr> <td colspan="2" style="padding-top:20px;"> <table border="0" cellpadding="0" cellspacing="0"> <tr> <td style="padding-right:8px;"><span style="display:inline-block; padding:5px 12px; background:{statusColor}22; border:1px solid {statusColor}88; border-radius:20px; font-size:11px; font-weight:700; color:{statusColor};">&bull; {overallStatus}</span></td> <td style="padding-right:8px;"><span style="display:inline-block; padding:5px 12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); border-radius:20px; font-size:11px; font-weight:600; color:#cbd5e1;"><span style="color:#64748b; font-weight:700; text-transform:uppercase; font-size:9px; margin-right:4px;">Tenants:</span>{tenantCount}</span></td> <td style="padding-right:8px;"><span style="display:inline-block; padding:5px 12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); border-radius:20px; font-size:11px; font-weight:600; color:#cbd5e1;"><span style="color:#64748b; font-weight:700; text-transform:uppercase; font-size:9px; margin-right:4px;">Localities:</span>{totalLocalities}</span></td> <td><span style="display:inline-block; padding:5px 12px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.12); border-radius:20px; font-size:11px; font-weight:600; color:#cbd5e1;"><span style="color:#64748b; font-weight:700; text-transform:uppercase; font-size:9px; margin-right:4px;">Runtime:</span>{duration}</span></td> </tr> </table> </td> </tr> </table> </td> </tr> <!-- EXECUTIVE SUMMARY --> <tr> <td style="padding:24px 36px 12px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="background:linear-gradient(135deg, #f8faff 0%, #f1f5fd 100%); border:1px solid #dbeafe; border-left:4px solid #4f46e5; border-radius:12px; padding:16px 20px;"> <tr> <td> <div style="font-size:10px; font-weight:800; letter-spacing:1px; text-transform:uppercase; color:#4f46e5; margin-bottom:4px;">Executive Summary</div> <div style="font-size:13px; color:#334155; line-height:1.6;">The scheduled billing cycle for <strong style="color:#0f172a;">{primaryCity}</strong> processed <strong style="color:#0f172a;">{totalScheduled} records</strong> across <strong style="color:#0f172a;">{totalLocalities} locality batches</strong>. A total of <strong style="color:#059669;">{totalSuccess} bills</strong> were generated representing <strong style="color:#2563eb;">&#8377; {totalAmount}</strong> in billed revenue with <strong style="color:#dc2626;">{totalFailure} failures</strong> ({successRate}% success rate).</div> </td> </tr> </table> </td> </tr> <!-- KPI TILES (2x2) --> <tr> <td style="padding:16px 36px 24px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <!-- KPI 1: Scheduled --> <td width="48%" valign="top" style="background:#ffffff; border:1px solid #e2e8f0; border-radius:14px; padding:18px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <td> <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.8px; color:#64748b;">Scheduled Records</div> <div style="font-size:26px; font-weight:800; color:#0f172a; margin-top:6px;">{totalScheduled}</div> <div style="font-size:11px; color:#94a3b8; margin-top:4px;">Total targeted consumers</div> </td> <td align="right" valign="top"><div style="width:34px; height:34px; background:#f1f5f9; border-radius:10px; text-align:center; line-height:34px; font-size:15px;">&#128203;</div></td> </tr> </table> </td> <td width="4%"></td> <!-- KPI 2: Bills Generated --> <td width="48%" valign="top" style="background:linear-gradient(135deg, #ffffff 0%, #f0fdf4 100%); border:1px solid #bbf7d0; border-radius:14px; padding:18px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <td> <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.8px; color:#15803d;">Bills Generated</div> <div style="font-size:26px; font-weight:800; color:#15803d; margin-top:6px;">{totalSuccess}</div> <div style="font-size:11px; color:#16a34a; margin-top:4px;">Successfully created</div> </td> <td align="right" valign="top"><div style="width:34px; height:34px; background:#dcfce7; border-radius:10px; text-align:center; line-height:34px; font-size:15px;">&#10003;</div></td> </tr> </table> </td> </tr> <tr><td height="14" colspan="3"></td></tr> <tr> <!-- KPI 3: Failed — shows success rate --> <td width="48%" valign="top" style="background:linear-gradient(135deg, #ffffff 0%, #fff1f2 100%); border:1px solid #fecdd3; border-radius:14px; padding:18px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <td> <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.8px; color:#be123c;">Failed / Skipped</div> <div style="font-size:26px; font-weight:800; color:#be123c; margin-top:6px;">{totalFailure}</div> <div style="font-size:11px; color:#e11d48; margin-top:4px;">{successRate}% success rate</div> </td> <td align="right" valign="top"><div style="width:34px; height:34px; background:#ffe4e6; border-radius:10px; text-align:center; line-height:34px; font-size:15px;">&#9888;</div></td> </tr> </table> </td> <td width="4%"></td> <!-- KPI 4: Amount --> <td width="48%" valign="top" style="background:linear-gradient(135deg, #ffffff 0%, #eff6ff 100%); border:1px solid #bfdbfe; border-radius:14px; padding:18px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0"> <tr> <td> <div style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.8px; color:#1d4ed8;">Total Billed Amount</div> <div style="font-size:24px; font-weight:800; color:#1d4ed8; margin-top:6px;">&#8377; {totalAmount}</div> <div style="font-size:11px; color:#2563eb; margin-top:4px;">Generated demand value</div> </td> <td align="right" valign="top"><div style="width:34px; height:34px; background:#dbeafe; border-radius:10px; text-align:center; line-height:34px; font-size:15px;">&#128176;</div></td> </tr> </table> </td> </tr> </table> </td> </tr> <!-- LOCALITY BREAKDOWN --> <tr> <td style="padding:10px 36px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td><div style="font-size:15px; font-weight:800; color:#0f172a;">Locality &amp; Group Breakdown</div></td> <td align="right"><span style="font-size:11px; color:#64748b; font-weight:600;">{totalLocalities} Batch Groups</span></td> </tr> </table> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0; border-radius:12px; overflow:hidden; font-size:12.5px; border-collapse:collapse; background:#ffffff;"> <thead> <tr style="background:#f8fafc; border-bottom:2px solid #e2e8f0;"> <th style="padding:12px 10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:center; width:36px;">#</th> <th style="padding:12px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:left;">Locality / Group</th> <th style="padding:12px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:left;">City</th> <th style="padding:12px 10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:right;">Scheduled</th> <th style="padding:12px 10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:right;">Success</th> <th style="padding:12px 10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:right;">Failed</th> <th style="padding:12px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:right;">Amount</th> <th style="padding:12px 10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#64748b; text-align:center;">Status</th> </tr> </thead> <tbody>{localityRows}</tbody> </table> </td> </tr> <!-- FAILURE SECTION --> <tr> <td style="padding:10px 36px 20px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td><div style="font-size:15px; font-weight:800; color:#0f172a;">Failure &amp; Exception Summary</div></td> <td align="right"><span style="font-size:11px; color:#e11d48; font-weight:700;">{totalFailure} Issues Found</span></td> </tr> </table> <!-- Common Failure Reason Banner (hidden when no failures) --> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="margin-bottom:12px; background:#fff7ed; border:1px solid #fed7aa; border-left:4px solid #f97316; border-radius:10px; padding:12px 16px;"> <tr> <td> <div style="font-size:10px; font-weight:800; text-transform:uppercase; color:#c2410c; letter-spacing:0.8px; margin-bottom:4px;">&#9888; Most Common Failure Reason</div> <div style="font-size:12.5px; color:#7c2d12; font-weight:600; line-height:1.5;">{commonFailureReason}</div> </td> </tr> </table> <!-- Failures Table --> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="border:1px solid #fecdd3; border-radius:12px; overflow:hidden; font-size:12px; border-collapse:collapse; background:#ffffff;"> <thead> <tr style="background:#fff1f2; border-bottom:1px solid #fecdd3;"> <th style="padding:10px; font-size:10px; font-weight:700; text-transform:uppercase; color:#9f1239; text-align:center; width:36px;">#</th> <th style="padding:10px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#9f1239; text-align:left;">Consumer Code</th> <th style="padding:10px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#9f1239; text-align:left;">Locality</th> <th style="padding:10px 12px; font-size:10px; font-weight:700; text-transform:uppercase; color:#9f1239; text-align:left;">Reason</th> </tr> </thead> <tbody>{failedRows}</tbody> </table> </td> </tr> <!-- EXECUTION TIMELINE --> <tr> <td style="padding:10px 36px 26px;"> <table width="100%" border="0" cellpadding="0" cellspacing="0" style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; padding:16px 20px;"> <tr> <td width="25%" valign="top"> <div style="font-size:10px; font-weight:700; text-transform:uppercase; color:#94a3b8; letter-spacing:0.5px;">Started At</div> <div style="font-size:12.5px; font-weight:700; color:#1e293b; margin-top:3px;">{generatedOn}</div> </td> <td width="25%" valign="top"> <div style="font-size:10px; font-weight:700; text-transform:uppercase; color:#94a3b8; letter-spacing:0.5px;">Completed At</div> <div style="font-size:12.5px; font-weight:700; color:#1e293b; margin-top:3px;">{completedOn}</div> </td> <td width="25%" valign="top"> <div style="font-size:10px; font-weight:700; text-transform:uppercase; color:#94a3b8; letter-spacing:0.5px;">Execution Duration</div> <div style="font-size:12.5px; font-weight:700; color:#4f46e5; margin-top:3px;">{duration}</div> </td> <td width="25%" valign="top"> <div style="font-size:10px; font-weight:700; text-transform:uppercase; color:#94a3b8; letter-spacing:0.5px;">ULB / Tenant</div> <div style="font-size:12.5px; font-weight:700; color:#1e293b; margin-top:3px;">{primaryCity} ({primaryTenant})</div> </td> </tr> </table> </td> </tr> <!-- FOOTER --> <tr> <td style="background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 36px; text-align:center;"> <div style="font-size:11.5px; color:#475569; font-weight:600;">mSeva UPYOG &nbsp;&bull;&nbsp; Water &amp; Sewerage Calculation Engine</div> <div style="font-size:10.5px; color:#94a3b8; margin-top:4px;">This is an automated system generated report &bull; Generated on {completedOn}</div> </td> </tr> </table> </td> </tr> </table> </body> </html>',
    'pb',
    'rainmaker-ws',
    0,
    NOW(),
    0,
